// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

/** A result waiting for the verifier (critical values first, then STAT). */
export interface VerificationItemOut {
  result_id: number;
  lab_requisition_item_id: number;
  code: string;
  test_name: string;
  metrics_jsonb: Record<string, unknown>;
  flags_jsonb: Record<string, "N" | "L" | "H" | "CL" | "CH" | "C">;
  has_critical_value: boolean;
  interpretation: string | null;
  entered_at: string;
  /** The user who entered the result: compare it with the signed-in user's user_id (never the names); the same person may not verify it (LAB_VERIFIER_MUST_DIFFER) */
  entered_by: number;
  entered_by_name: string;
  is_correction: boolean;
  /** Its requisition: GET /lab/requisitions/{requisition_id} has the whole order, and after a lost verify answer tells whether this result was published or rejected */
  requisition_id: number;
  requisition_number: string;
  patient_id: number;
  patient_name: string;
  mrn: string;
  priority: "Routine" | "Urgent" | "STAT";
  /** The sample's barcode */
  barcode: string | null;
  /** When the test was due: the turnaround clock from the sample's receipt (MSDS AAC 4); null when the sample has no receipt or collection time */
  due_at: string | null;
  /** due_at has passed (the server's clock): ask for the optional delay_reason before verifying. Never true for a correction (is_correction) */
  is_overdue: boolean;
}

export interface VerifyIn {
  decision: "Verified" | "Rejected";
  /** Mandatory when rejecting */
  note?: string | null;
  /** A result published after its due time (`due_at`): why it was late (the turnaround report, MSDS AAC 4) */
  delay_reason?: string | null;
}

export interface LabResultOut {
  result_id: number;
  lab_requisition_item_id: number;
  sample_id: number | null;
  metrics_jsonb: Record<string, unknown>;
  flags_jsonb: Record<string, "N" | "L" | "H" | "CL" | "CH" | "C">;
  has_critical_value: boolean;
  interpretation: string | null;
  status: "PendingVerification" | "Published" | "Rejected" | "Superseded";
  entered_by: number;
  entered_at: string;
  published_at: string | null;
  /** Set when an unverified critical value was shown to the ordering doctor: show 'Pending verification' */
  provisionally_released_at: string | null;
  is_correction: boolean;
  corrects_result_id: number | null;
  correction_reason: string | null;
  /** Sent out: the partner laboratory that performed it */
  partner_id: number | null;
  partner_report_ref: string | null;
  partner_reported_at: string | null;
  row_version: number;
}

/** A requisition with its tests, samples, results (only published ones for the ordering doctor) and bill. */
export interface LabRequisitionDetailOut {
  requisition_id: number;
  requisition_number: string;
  patient_id: number;
  ticket_id: number | null;
  admission_id: number | null;
  requester_type: "Doctor" | "Receptionist" | "LabAdmin" | "System";
  requester_user_id: number;
  requester_doctor_id: number | null;
  is_lab_only_walkin: boolean;
  priority: "Routine" | "Urgent" | "STAT";
  clinical_notes: string | null;
  status: "Pending" | "InProgress" | "Completed" | "Cancelled";
  cancel_reason: string | null;
  ordered_at: string;
  row_version: number;
  patient_name: string;
  mrn: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  dob: string | null;
  doctor_name: string | null;
  items: RequisitionItemOut[];
  results: RequisitionResultOut[];
  invoice: LabInvoiceStatusOut | null;
}

export interface RequisitionItemOut {
  lab_requisition_item_id: number;
  test_id: number;
  code: string;
  test_name: string;
  section: string;
  price_at_order: number;
  status: "Ordered" | "SampleCollected" | "Processing" | "PendingVerification" | "Published" | "ReRunRequired" | "Cancelled";
  rerun_of_item_id: number | null;
  is_billable: boolean;
  sample_id: number | null;
  barcode: string | null;
  sample_status: "Pending" | "Collected" | "Received" | "Dispatched" | "Rejected" | "Consumed" | null;
  collected_at: string | null;
  received_at: string | null;
  identity_check: "WristbandScan" | "TwoIdentifiers" | "EmergencyOverride" | "SameSpecimen" | null;
  /** Done by a partner laboratory (tell the patient) */
  is_send_out: boolean;
  partner_name: string | null;
  /** When the result is due (the turnaround clock starts at the sample's receipt) */
  due_at: string | null;
}

export interface RequisitionResultOut {
  result_id: number;
  lab_requisition_item_id: number;
  /** Metric key -> value */
  metrics_jsonb: Record<string, unknown>;
  /** Metric key -> its flag (a text metric only when critical: C) */
  flags_jsonb: Record<string, "N" | "L" | "H" | "CL" | "CH" | "C">;
  has_critical_value: boolean;
  interpretation: string | null;
  status: "PendingVerification" | "Published" | "Rejected" | "Superseded";
  entered_at: string;
  published_at: string | null;
  /** Set when an unverified critical value was shown to the ordering doctor: show 'Pending verification' */
  provisionally_released_at: string | null;
  is_correction: boolean;
  corrects_result_id: number | null;
  correction_reason: string | null;
  /** Sent out: the partner laboratory that performed it (MSDS AAC 6) */
  partner_name: string | null;
  partner_report_ref: string | null;
  /** The technician who entered the result (MSDS 147) */
  performed_stamp: AuthorStampOut;
  /** The verifier who released it (null until verified) */
  verified_stamp: AuthorStampOut | null;
}

/** The author stamp of a clinical entry (MSDS IMS 147), as the author's staff record stood when they signed it (SQL hms_author_stamp / hms_employee_stamp, migration 0013 [STP]). Show it under the entry on screen and print `text` under it on paper. */
export interface AuthorStampOut {
  employee_id: number | null;
  user_id: number | null;
  name: string;
  /** Designation and specialty, e.g. "Medical Officer, General Medicine" */
  designation: string | null;
  /** Council registration, e.g. "PMDC 12345-P" or "PNC 67890" */
  registration: string | null;
  /** When the entry was signed, reported or verified */
  at: string;
  /** The printed line: name, designation, registration, date and time */
  text: string;
}

export interface LabInvoiceStatusOut {
  invoice_id: number;
  invoice_no: string;
  invoice_type: "OPD" | "IPD" | "Pharmacy" | "Lab" | "Imaging" | "OT" | "OTC" | "Other";
  status: "Draft" | "Open" | "PartiallyPaid" | "Paid" | "CreditAuthorized" | "Waivered" | "Refunded" | "Cancelled";
  /** Samples of an unpaid OPD / walk-in bill wait for payment */
  balance_due: number;
}

export interface PrintOut_LabReportFieldsOut_ {
  document_type: "autopsy_order" | "bed_labels" | "blood_component_label" | "blood_donation_labels" | "clinical_note" | "complaint_letter" | "complaints_notice" | "consent_form" | "cost_estimate" | "cssd_labels" | "death_certificate" | "discharge_summary" | "dispensing_label" | "dose_label" | "id_card" | "imaging_report" | "lab_label" | "lab_report" | "mlc_intimation" | "opd_slip" | "pharmacy_receipt" | "prescription" | "referral_slip" | "send_out_manifest" | "surgical_record" | "triage_algorithm" | "wristband";
  /** Which printer of the terminal to use (GET /api/v1/terminals/whoami) */
  printer_role: "receipt" | "label" | "document" | "card";
  paper_width_mm: number;
  /** The document's data, for frontends that render their own layout */
  fields: LabReportFieldsOut;
  /** Pre-formatted monospace text (48 columns) for ESC/POS printers, as is */
  text: string | null;
  barcode_svg: string | null;
  qr_svg: string | null;
  pdf_url: string | null;
}

/** The fields of a printed lab report (`GET /lab/requisitions/{id}/report/print-payload`). */
export interface LabReportFieldsOut {
  /** name, address, phone, phc_number (empty until confirmed) */
  hospital: Record<string, string>;
  requisition_number: string;
  patient_name: string;
  mrn: string;
  gender: "male" | "female" | "other" | "unknown" | null;
  age_years: number | null;
  doctor_name: string | null;
  ordered_at: string;
  /** False while some tests of the requisition are still in the lab (a partial report) */
  complete: boolean;
  results: LabReportResultOut[];
}

/** One published test of a printed lab report. */
export interface LabReportResultOut {
  result_id: number;
  code: string;
  test_name: string;
  section: string;
  rows: LabReportRowOut[];
  interpretation: string | null;
  has_critical_value: boolean;
  is_correction: boolean;
  correction_reason: string | null;
  published_at: string | null;
  /** Sent out (MSDS AAC 6): the partner, its PHC registration and its report number */
  performed_by_partner: string | null;
  performed_stamp: AuthorStampOut;
  verified_stamp: AuthorStampOut | null;
}

/** One metric of a reported test, with the reference range for this patient's sex. */
export interface LabReportRowOut {
  key: string;
  label: string;
  /** A number, or text for a text metric */
  value: unknown;
  unit: string | null;
  /** e.g. "13.5 - 17.5" */
  reference: string | null;
  flag: "N" | "L" | "H" | "CL" | "CH" | "C" | null;
}

/** Results awaiting verification (critical & STAT first) — GET /api/v1/lab/verification-queue (who may call: holders of lab.result.verify). */
export function verificationQueue(): Promise<VerificationItemOut[]> {
  return api<VerificationItemOut[]>("GET", `/lab/verification-queue`, undefined);
}

/** Verify (publish + notify doctor) or reject back to the bench — POST /api/v1/lab/results/{result_id}/verify (who may call: holders of lab.result.verify). */
export function verifyLabResults(result_id: number, body: VerifyIn): Promise<LabResultOut> {
  return api<LabResultOut>("POST", `/lab/results/${result_id}/verify`, body);
}

/** Requisition with items, samples, results and bill status — GET /api/v1/lab/requisitions/{requisition_id} (who may call: holders of lab.requisition.view or lab.result.view). */
export function getRequisitionLabRequisitions(requisition_id: number): Promise<LabRequisitionDetailOut> {
  return api<LabRequisitionDetailOut>("GET", `/lab/requisitions/${requisition_id}`, undefined);
}

/** Printable lab report with who performed and who verified each test — GET /api/v1/lab/requisitions/{requisition_id}/report/print-payload (who may call: holders of lab.requisition.view or lab.result.view). */
export function reportPrintLabRequisitionsPayload(requisition_id: number): Promise<PrintOut_LabReportFieldsOut_> {
  return api<PrintOut_LabReportFieldsOut_>("GET", `/lab/requisitions/${requisition_id}/report/print-payload`, undefined);
}

/** The lab report as a PDF — GET /api/v1/lab/requisitions/{requisition_id}/report/pdf (who may call: holders of lab.requisition.view or lab.result.view). */
export function reportPdfLabRequisitions(requisition_id: number): Promise<unknown> {
  return api<unknown>("GET", `/lab/requisitions/${requisition_id}/report/pdf`, undefined);
}
